  final DigestMultibase? pendingKeyFingerprint;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'algorithm': algorithm.value,
        'keyFingerprint': keyFingerprint,
        if (publicKeyJwk != null) 'publicKeyJwk': publicKeyJwk!.toJson(),
        if (certificatePem != null) 'certificatePem': certificatePem!,
        if (address != null) 'address': address!,
        if (pendingKeyFingerprint != null)
          'pendingKeyFingerprint': pendingKeyFingerprint!,
      };
}

/// That a static model's secret is set, and which one. Never its value.
class AccountSecretInfo {
  const AccountSecretInfo({
    required this.fingerprint,
    required this.setAt,
  });

  /// Read this payload from a decoded JSON object.
  factory AccountSecretInfo.fromJson(Map<String, dynamic> json) =>
      AccountSecretInfo(
        fingerprint: json['fingerprint'] as String,
        setAt: json['setAt'] as String,
      );

  /// A keyed digest of the secret (HMAC under a custodian-held key), so the fingerprint
  /// confirms a re-entered value without being a dictionary oracle for anyone who reads
  /// it.
  final DigestMultibase fingerprint;
  final String setAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'fingerprint': fingerprint,
        'setAt': setAt,
      };
}

/// An object-key prefix within the account's bucket: one or more segments of lowercase
/// letters, digits, `.`, `_` and `-`, each beginning with a letter or digit and ending
/// with `/`. No quote, backslash, wildcard, whitespace, `..` segment or empty segment
/// can appear. That is deliberate: the custodian places this value inside a provider
/// policy — an IAM session policy (JSON), a GCS Credential Access Boundary condition
/// (CEL) — and a value able to carry a metacharacter can break out of the string it is
/// placed in and widen the policy. That is a known class of defect (CVE-2026-42811, a
/// CEL injection in downscoped GCS credentials). Even with this pattern, a custodian
/// MUST build provider policies with the provider language's own encoder, never by
/// string interpolation.
typedef ProviderObjectPrefix = String;

/// `put`: write an object. `get`: read one. `delete`: remove one. No list, ACL, policy
/// or bucket-level action exists here, so none can be granted.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const ProviderObjectAction(String value) {
  static const ProviderObjectAction put = ProviderObjectAction('put');
  static const ProviderObjectAction get = ProviderObjectAction('get');
  static const ProviderObjectAction delete = ProviderObjectAction('delete');

  /// Every value this specification's schema permits.
  static const List<ProviderObjectAction> values = <ProviderObjectAction>[
    put,
    get,
    delete
  ];
}

/// The widest scope a binding's consumer may request. An issuance is inside the
/// ceiling when its `prefix` begins with one of `prefixes`, every one of its `actions`
/// is in `actions`, and every one of its `scopes` is in `scopes`. Absent members
/// confer nothing: a ceiling with no `prefixes` permits no storage issuance.
class CredentialScopeCeiling {
  const CredentialScopeCeiling({
    this.prefixes,
    this.actions,
    this.scopes,
  });

  /// Read this payload from a decoded JSON object.
  factory CredentialScopeCeiling.fromJson(Map<String, dynamic> json) =>
      CredentialScopeCeiling(
        prefixes: json['prefixes'] == null
            ? null
            : (json['prefixes'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        actions: json['actions'] == null
            ? null
            : (json['actions'] as List<dynamic>)
                .map((e) => ProviderObjectAction(e as String))
                .toList(),
        scopes: json['scopes'] == null
            ? null
            : (json['scopes'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
      );

  final List<ProviderObjectPrefix>? prefixes;
  final List<ProviderObjectAction>? actions;
  final List<String>? scopes;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        if (prefixes != null) 'prefixes': prefixes!,
        if (actions != null) 'actions': actions!.map((e) => e.value).toList(),
        if (scopes != null) 'scopes': scopes!,
      };
}

/// Who may use an account, and how far. One binding per consumer per account. A
/// binding is checked before anything is signed: the caller must be `consumer`, proven
/// by the request's own proof; the request must sit inside `scopeCeiling`; its TTL
/// must not exceed `maxTtlSeconds`; and the binding's rate must not be exhausted.
class AccountBinding {
  const AccountBinding({
    required this.consumer,
    this.scopeCeiling,
    required this.maxTtlSeconds,
    required this.ratePerMinute,
    this.sourceCidrs,
    this.grantedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory AccountBinding.fromJson(Map<String, dynamic> json) => AccountBinding(
        consumer: json['consumer'] as String,
        scopeCeiling: json['scopeCeiling'] == null
            ? null
            : CredentialScopeCeiling.fromJson(
                json['scopeCeiling'] as Map<String, dynamic>),
        maxTtlSeconds: json['maxTtlSeconds'] as int,
        ratePerMinute: json['ratePerMinute'] as int,
        sourceCidrs: json['sourceCidrs'] == null
            ? null
            : (json['sourceCidrs'] as List<dynamic>)
                .map((e) => e as String)
                .toList(),
        grantedAt: json['grantedAt'] as String?,
      );

  /// The DID of the integration allowed to use the account.
  final String consumer;

  /// Required for storage and OAuth models; absent for `sui-signer`, whose ceiling is
  /// the account's own allow-list and caps.
  final CredentialScopeCeiling? scopeCeiling;

  /// The longest credential lifetime the consumer may request. 900 (15 minutes) is
  /// RECOMMENDED; the ceiling is one hour.
  final int maxTtlSeconds;

  /// Issuances or signatures per minute for this binding.
  final int ratePerMinute;

  /// Where the provider supports it (`aws:SourceIp`), issued credentials are pinned to
  /// these networks, so a credential lifted from the consumer is useless elsewhere.
  final List<String>? sourceCidrs;
  final String? grantedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'consumer': consumer,
        if (scopeCeiling != null) 'scopeCeiling': scopeCeiling!.toJson(),
        'maxTtlSeconds': maxTtlSeconds,
        'ratePerMinute': ratePerMinute,
        if (sourceCidrs != null) 'sourceCidrs': sourceCidrs!,
        if (grantedAt != null) 'grantedAt': grantedAt!,
      };
}

/// `sign`: the custodian signed its assertion, session request or test transaction.
/// `exchange`: the provider issued a credential for it. `put`, `get`, `delete`: one
/// canary object at the narrowest scope of the account's bindings. `decode`: for
/// `sui-signer`, a built test transaction passed the allow-list (it is never
/// submitted).
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const AccountProbeStep(String value) {
  static const AccountProbeStep sign = AccountProbeStep('sign');
  static const AccountProbeStep exchange = AccountProbeStep('exchange');
  static const AccountProbeStep put = AccountProbeStep('put');
  static const AccountProbeStep get = AccountProbeStep('get');
  static const AccountProbeStep delete = AccountProbeStep('delete');
  static const AccountProbeStep decode = AccountProbeStep('decode');

  /// Every value this specification's schema permits.
  static const List<AccountProbeStep> values = <AccountProbeStep>[
    sign,
    exchange,
    put,
    get,
    delete,
    decode
  ];
}

/// AccountProbeReportStepsItem, generated from its schema.
class AccountProbeReportStepsItem {
  const AccountProbeReportStepsItem({
    required this.step,
    required this.ok,
    this.durationMs,
    this.providerError,
    this.providerRequestId,
  });

  /// Read this payload from a decoded JSON object.
  factory AccountProbeReportStepsItem.fromJson(Map<String, dynamic> json) =>
      AccountProbeReportStepsItem(
        step: AccountProbeStep(json['step'] as String),
        ok: json['ok'] as bool,
        durationMs: json['durationMs'] as int?,
        providerError: json['providerError'] as String?,
        providerRequestId: json['providerRequestId'] as String?,
      );

  final AccountProbeStep step;
  final bool ok;
  final int? durationMs;

  /// The provider's error, verbatim and truncated, so an administrator sees the cloud's
  /// own words. Untrusted text. A custodian MUST remove any credential, signature or
  /// token from it first.
  final String? providerError;
  final String? providerRequestId;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'step': step.value,
        'ok': ok,
        if (durationMs != null) 'durationMs': durationMs!,
        if (providerError != null) 'providerError': providerError!,
        if (providerRequestId != null) 'providerRequestId': providerRequestId!,
      };
}

/// AccountProbeReport
class AccountProbeReport {
  const AccountProbeReport({
    required this.at,
    required this.ok,
    required this.steps,
  });

  /// Read this payload from a decoded JSON object.
  factory AccountProbeReport.fromJson(Map<String, dynamic> json) =>
      AccountProbeReport(
        at: json['at'] as String,
        ok: json['ok'] as bool,
        steps: (json['steps'] as List<dynamic>)
            .map((e) =>
                AccountProbeReportStepsItem.fromJson(e as Map<String, dynamic>))
            .toList(),
      );

  final String at;

  /// True when every step succeeded.
  final bool ok;

  /// In order; the first failing step ends the probe.
  final List<AccountProbeReportStepsItem> steps;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'at': at,
        'ok': ok,
        'steps': steps.map((e) => e.toJson()).toList(),
      };
}

/// An account as every read returns it. Contains no private key, no secret and no
/// issued credential, to any reader.
class ExternalAccount {
  const ExternalAccount({
    required this.id,
    required this.label,
    required this.context,
    required this.settings,
    required this.state,
    this.publicMaterial,
    this.secret,
    required this.bindings,
    required this.egressHosts,
    required this.providerSetupRequired,
    this.lastProbe,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory ExternalAccount.fromJson(Map<String, dynamic> json) =>
      ExternalAccount(
        id: json['id'] as String,
        label: json['label'] as String,
        context: json['context'] as String,
        settings: json['settings'],
        state: AccountState(json['state'] as String),
        publicMaterial: json['publicMaterial'] == null
            ? null
            : AccountPublicMaterial.fromJson(
                json['publicMaterial'] as Map<String, dynamic>),
        secret: json['secret'] == null
            ? null
            : AccountSecretInfo.fromJson(
                json['secret'] as Map<String, dynamic>),
        bindings: (json['bindings'] as List<dynamic>)
            .map((e) => AccountBinding.fromJson(e as Map<String, dynamic>))
            .toList(),
        egressHosts: (json['egressHosts'] as List<dynamic>)
            .map((e) => e as String)
            .toList(),
        providerSetupRequired: json['providerSetupRequired'] as bool,
        lastProbe: json['lastProbe'] == null
            ? null
            : AccountProbeReport.fromJson(
                json['lastProbe'] as Map<String, dynamic>),
        createdAt: json['createdAt'] as String,
        updatedAt: json['updatedAt'] as String,
      );

  final AccountId id;

  /// Display name. Untrusted text: render it, never interpret it.
  final String label;
  final AccountContextId context;
  final AccountSettings settings;
  final AccountState state;

  /// Absent for the static models, which hold a secret rather than a key.
  final AccountPublicMaterial? publicMaterial;

  /// Static models only; absent until the secret is set.
  final AccountSecretInfo? secret;
  final List<AccountBinding> bindings;

  /// The provider hosts this account's use connects to, derived by the custodian from
  /// its settings. The custodian MUST NOT connect anywhere else on this account's
  /// behalf, so an egress proxy can allow exactly this set. Empty for models that need
  /// no egress.
  final List<String> egressHosts;

  /// True when the account cannot be used until its provider-side setup is redone: after
  /// a restore that could not carry its key or secret (a wrapped RSA key, a static
  /// secret), or after a rotation awaiting confirmation.
  final bool providerSetupRequired;
  final AccountProbeReport? lastProbe;
  final String createdAt;
  final String updatedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'id': id,
        'label': label,
        'context': context,
        'settings': settings,
        'state': state.value,
        if (publicMaterial != null) 'publicMaterial': publicMaterial!.toJson(),
        if (secret != null) 'secret': secret!.toJson(),
        'bindings': bindings.map((e) => e.toJson()).toList(),
        'egressHosts': egressHosts,
        'providerSetupRequired': providerSetupRequired,
        if (lastProbe != null) 'lastProbe': lastProbe!.toJson(),
        'createdAt': createdAt,
        'updatedAt': updatedAt,
      };
}

