use, restorable. Deletion removes the record."},"AccountSettings":{"title":"AccountSettings","description":"Per-model account settings, discriminated by `model`. Never a secret: every value here is returned to anyone who may read the account.","oneOf":[{"\$ref":"#/\$defs/AwsRolesAnywhereSettings"},{"\$ref":"#/\$defs/GcpWifPinnedSettings"},{"\$ref":"#/\$defs/AzureCertSettings"},{"\$ref":"#/\$defs/OAuth2PrivateKeyJwtSettings"},{"\$ref":"#/\$defs/S3StaticPresignSettings"},{"\$ref":"#/\$defs/SuiSignerSettings"},{"\$ref":"#/\$defs/StaticSecretSettings"}]},"StaticSecretSettings":{"title":"StaticSecretSettings","type":"object","additionalProperties":false,"required":["model","driver","baseUrl"],"description":"Egress: the host of `baseUrl`. The secret is set with external/accounts/secret/set and used only inside the custodian by `driver`; a provider reachable only by handing the consumer the raw key is not supported.","properties":{"model":{"type":"string","const":"static-secret"},"driver":{"type":"string","maxLength":64,"pattern":"^[a-z0-9][a-z0-9-]*\$","description":"The custodian\'s driver that uses the secret: performs a login or token exchange and returns a short-lived result. A custodian refuses a driver it does not implement."},"baseUrl":{"\$ref":"#/\$defs/ProviderHttpsUrl"}}},"ProviderHttpsUrl":{"title":"ProviderHttpsUrl","type":"string","format":"uri","maxLength":2048,"pattern":"^https://[^\\\\s\\"\'\\\\\\\\]+\$"},"SuiSignerSettings":{"title":"SuiSignerSettings","type":"object","additionalProperties":false,"required":["model","network","allowedCalls","maxGasBudgetMist","maxGasPerDayMist"],"description":"No egress: the custodian signs and the consumer submits the transaction. The allow-list, the gas caps and the coin caps are the account\'s whole authority; a transaction outside them is refused before anything is signed.","properties":{"model":{"type":"string","const":"sui-signer"},"network":{"type":"string","enum":["mainnet","testnet","devnet"]},"allowedCalls":{"type":"array","minItems":1,"maxItems":32,"items":{"\$ref":"#/\$defs/SuiMoveCall"},"description":"Every MoveCall command in a signed transaction must name one of these. For Walrus storage: the system package\'s `register_blob`, `certify_blob`, `extend_blob` and `delete_blob`, and the coin calls needed to pay for them."},"allowedObjects":{"type":"array","maxItems":32,"items":{"type":"string","pattern":"^0x[0-9a-f]{64}\$"},"description":"Shared objects a transaction may take as input, such as the Walrus system and staking objects. Absent means any object the allowed calls accept."},"maxGasBudgetMist":{"type":"integer","minimum":1,"description":"The largest gas budget one transaction may declare."},"maxGasPerDayMist":{"type":"integer","minimum":1,"description":"The total gas budget signed per rolling 24 hours."},"maxCoinOutPerTx":{"type":"array","maxItems":8,"items":{"type":"object","additionalProperties":false,"required":["coinType","amount"],"properties":{"coinType":{"type":"string","maxLength":512,"pattern":"^0x[0-9a-f]{1,64}::[A-Za-z0-9_]+::[A-Za-z0-9_]+\$"},"amount":{"type":"integer","minimum":0}}},"description":"Per coin type, the most a single transaction may spend or transfer out of the account\'s address, in the coin\'s smallest unit. A coin type not listed may not leave the address at all."}}},"SuiMoveCall":{"title":"SuiMoveCall","type":"object","additionalProperties":false,"required":["package","module","function"],"description":"One Move function an account\'s transactions may call.","properties":{"package":{"type":"string","pattern":"^0x[0-9a-f]{64}\$"},"module":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_]{0,127}\$"},"function":{"type":"string","pattern":"^[A-Za-z][A-Za-z0-9_]{0,127}\$"}}},"S3StaticPresignSettings":{"title":"S3StaticPresignSettings","type":"object","additionalProperties":false,"required":["model","endpoint","region","bucket","accessKeyId"],"description":"No egress: presigning is a computation inside the custodian, and the consumer uses the URL itself.","properties":{"model":{"type":"string","const":"s3-static-presign"},"endpoint":{"\$ref":"#/\$defs/ProviderHttpsUrl"},"region":{"type":"string","maxLength":64,"pattern":"^[a-z0-9-]+\$","description":"The SigV4 signing region; `auto` for Cloudflare R2."},"bucket":{"\$ref":"#/\$defs/ProviderBucketName"},"pathStyle":{"type":"boolean","description":"Address the bucket in the path rather than the host name, as MinIO usually needs."},"accessKeyId":{"type":"string","maxLength":128,"pattern":"^[A-Za-z0-9]+\$","description":"The access key\'s identifier. Not a secret: it appears in every presigned URL. The secret half is set with external/accounts/secret/set and never returned."}}},"ProviderBucketName":{"title":"ProviderBucketName","type":"string","minLength":3,"maxLength":63,"pattern":"^[a-z0-9][a-z0-9.-]*[a-z0-9]\$","description":"A bucket name as S3 and GCS accept it. Validated rather than free so that it can be placed in a provider policy without escaping."},"OAuth2PrivateKeyJwtSettings":{"title":"OAuth2PrivateKeyJwtSettings","type":"object","additionalProperties":false,"required":["model","tokenEndpoint","clientId"],"description":"Egress: the host of `tokenEndpoint`, and nothing else.","properties":{"model":{"type":"string","const":"oauth2-private-key-jwt"},"tokenEndpoint":{"\$ref":"#/\$defs/ProviderHttpsUrl"},"clientId":{"type":"string","minLength":1,"maxLength":512,"pattern":"^[!-~]+\$"},"audience":{"type":"string","maxLength":2048,"pattern":"^[!-~]+\$","description":"The assertion\'s `aud`. Absent means `tokenEndpoint`."},"scopes":{"type":"array","maxItems":64,"uniqueItems":true,"items":{"type":"string","maxLength":256,"pattern":"^[!#-\\\\[\\\\]-~]+\$"},"description":"The scopes a binding may request, the ceiling for every issuance."},"signingAlgorithm":{"type":"string","enum":["ES256","RS256"]}}},"AzureCertSettings":{"title":"AzureCertSettings","type":"object","additionalProperties":false,"required":["model","tenantId","clientId","tokenScope"],"description":"Egress: `login.microsoftonline.com`, or the sovereign-cloud authority named in `authorityHost`.","properties":{"model":{"type":"string","const":"azure-cert"},"tenantId":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$"},"clientId":{"type":"string","pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\$"},"tokenScope":{"type":"string","maxLength":512,"pattern":"^[A-Za-z0-9:/._-]+\$","description":"The `scope` requested at the token endpoint, such as `https://storage.azure.com/.default`."},"authorityHost":{"type":"string","maxLength":253,"pattern":"^[a-z0-9.-]+\$","description":"Absent means `login.microsoftonline.com`."}}},"GcpWifPinnedSettings":{"title":"GcpWifPinnedSettings","type":"object","additionalProperties":false,"required":["model","projectNumber","poolId","providerId"],"description":"Egress: `sts.googleapis.com`, plus `iamcredentials.googleapis.com` when `serviceAccount` is set.","properties":{"model":{"type":"string","const":"gcp-wif-pinned"},"projectNumber":{"type":"string","pattern":"^[0-9]{1,20}\$"},"poolId":{"type":"string","pattern":"^[a-z0-9-]{4,32}\$"},"providerId":{"type":"string","pattern":"^[a-z0-9-]{4,32}\$"},"serviceAccount":{"type":"string","maxLength":254,"pattern":"^[a-z0-9-]+@[a-z0-9-]+\\\\.iam\\\\.gserviceaccount\\\\.com\$","description":"When set, the federated token is exchanged for this service account\'s access token."},"signingAlgorithm":{"type":"string","enum":["ES256","RS256"],"description":"The ID-token algorithm. ES256 unless the provider refuses it. Absent means ES256."},"bucket":{"\$ref":"#/\$defs/ProviderBucketName","description":"The GCS bucket issuances are scoped within, by a Credential Access Boundary."}}},"AwsRolesAnywhereSettings":{"title":"AwsRolesAnywhereSettings","type":"object","additionalProperties":false,"required":["model","region","profileArn","roleArn","trustAnchorArn"],"description":"Egress: `rolesanywhere.<region>.amazonaws.com`, plus `sts.<region>.amazonaws.com` when `chainedRoleArn` is set.","properties":{"model":{"type":"string","const":"aws-roles-anywhere"},"region":{"\$ref":"#/\$defs/AwsRegion"},"trustAnchorArn":{"\$ref":"#/\$defs/AwsArn","description":"The trust anchor holding the custodian\'s CA certificate. Recorded after the administrator creates it from external/accounts/setup."},"profileArn":{"\$ref":"#/\$defs/AwsArn"},"roleArn":{"\$ref":"#/\$defs/AwsArn"},"chainedRoleArn":{"\$ref":"#/\$defs/AwsArn","description":"When set, every issuance chains an AssumeRole into this role carrying the downscoping session policy, for deployments whose Roles Anywhere profile cannot carry one per request. Caps a credential at one hour."},"bucket":{"\$ref":"#/\$defs/ProviderBucketName","description":"The S3 bucket issuances are scoped within. Required for an account whose bindings issue storage scopes."}}},"AwsArn":{"title":"AwsArn","type":"string","maxLength":2048,"pattern":"^arn:aws[a-z-]*:[a-z0-9-]+:[a-z0-9-]*:[0-9]{0,12}:[A-Za-z0-9+=,.@_/:-]+\$"},"AwsRegion":{"title":"AwsRegion","type":"string","pattern":"^[a-z]{2}(-gov)?-[a-z]+-[0-9]\$","maxLength":32},"AccountContextId":{"title":"AccountContextId","type":"string","minLength":1,"maxLength":256,"description":"The custodian context that owns the account. Act scope in this context decides who may manage the account and who may consume it; the account\'s keys are derived in this context\'s key space."},"AccountId":{"title":"AccountId","type":"string","minLength":1,"maxLength":64,"pattern":"^[a-z0-9][a-z0-9-]*\$","description":"The account\'s identifier within its context, chosen by whoever creates it. Lowercase letters, digits and hyphens, so that it can be embedded in a certificate subject, a token subject or a provider-side condition without escaping. Unique per context; never reused after deletion while anything that names it (a provider-side trust policy, an audit row) may still exist."}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
